import{walkCauseChain}from"#shared/errors.js";var HookNotFoundError=class extends Error{name=`HookNotFoundError`;token;constructor(e){super(`Hook not found`),this.token=e}};var NonRetryableError=class extends Error{name=`FatalError`;fatal=!0};function hasName(e,t){return typeof e==`object`&&e&&`message`in e&&`name`in e?e.name===t:!1}function anyCause(e,t){for(let n of walkCauseChain(e))if(t.some(e=>hasName(n,e)))return!0;return!1}function isHookNotFound(e){return hasName(e,`HookNotFoundError`)}function isHookConflict(e){return hasName(e,`HookConflictError`)}function isRunNotFound(e){return anyCause(e,[`WorkflowRunNotFoundError`])}function isRunExpired(e){return anyCause(e,[`RunExpiredError`,`StreamExpiredError`])}function isRunMissing(e){return anyCause(e,[`WorkflowRunNotFoundError`,`RunExpiredError`])}function isRunInactive(e){return isRunMissing(e)||anyCause(e,[`EntityConflictError`])}function isRunTargetGone(e){return anyCause(e,[`HookNotFoundError`,`WorkflowRunNotFoundError`,`RunExpiredError`,`EntityConflictError`])}export{HookNotFoundError,NonRetryableError,isHookConflict,isHookNotFound,isRunExpired,isRunInactive,isRunMissing,isRunNotFound,isRunTargetGone};